def rootCount(self, edges, guesses, k):
    from collections import defaultdict
    n = len(edges) + 1
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    guess_set = set(map(tuple, guesses))
    cnt = [0]
    def dfs(u, parent):
        for v in g[u]:
            if v != parent:
                if (u, v) in guess_set:
                    cnt[0] += 1
                dfs(v, u)
    dfs(0, -1)
    res = [0]
    def reroot(u, parent, cur):
        if cur >= k:
            res[0] += 1
        for v in g[u]:
            if v != parent:
                new_cur = cur - ((u, v) in guess_set) + ((v, u) in guess_set)
                reroot(v, u, new_cur)
    reroot(0, -1, cnt[0])
    return res[0]

def passThePillow(self, n, time):
    cycle = 2 * (n - 1)
    time %= cycle
    if time < n:
        return time + 1
    else:
        return 2 * n - 1 - time

def kthLargestLevelSum(self, root, k):
    from collections import deque
    if not root:
        return -1
    q = deque([root])
    sums = []
    while q:
        level_sum = 0
        for _ in range(len(q)):
            node = q.popleft()
            level_sum += node.val
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        sums.append(level_sum)
    if k > len(sums):
        return -1
    sums.sort(reverse=True)
    return sums[k - 1]

