def findMinimumTime(self, tasks):
    tasks.sort(key=lambda x: x[1])
    max_end = max(t[1] for t in tasks)
    run = [False] * (max_end + 1)
    for start, end, duration in tasks:
        # count already running slots in [start, end]
        already = sum(run[start:end+1])
        need = duration - already
        if need > 0:
            for t in range(end, start - 1, -1):
                if not run[t]:
                    run[t] = True
                    need -= 1
                    if need == 0:
                        break
    return sum(run)

class TodoList:
    def __init__(self):
        self.tasks = {}
