        if userId not in self.tasks:
            return []
        pending = [t for t in self.tasks[userId] if not t['done'] and tag in t['tags']]
        pending.sort(key=lambda x: x['due'])
        return [t['desc'] for t in pending]
    def completeTask(self, userId, taskId):
