def findScore(self, nums):
    n = len(nums)
    indexed = sorted(range(n), key=lambda i: (nums[i], i))
    marked = [False] * n
    score = 0
    for i in indexed:
        if not marked[i]:
            score += nums[i]
            marked[i] = True
            if i > 0:
