    return score

def repairCars(self, ranks, cars):
    import math
    lo, hi = 1, min(ranks) * cars * cars
    while lo < hi:
        mid = (lo + hi) // 2
        total = sum(int(math.isqrt(mid // r)) for r in ranks)
        if total >= cars:
