    return True

def makePrefSumNonNegative(self, nums):
    import heapq
    heap = []
    prefix = 0
    ops = 0
    for x in nums:
        prefix += x
        if x < 0:
            heapq.heappush(heap, x)
        while prefix < 0 and heap:
