def collectTheCoins(self, coins, edges):
    from collections import defaultdict
    n = len(coins)
    g = defaultdict(set)
    for u, v in edges:
        g[u].add(v)
        g[v].add(u)
    # Remove leaves without coins
    degree = [len(g[i]) for i in range(n)]
    queue = [i for i in range(n) if degree[i] == 1 and coins[i] == 0]
    for u in queue:
        for v in g[u]:
            g[v].discard(u)
            degree[v] -= 1
            if degree[v] == 1 and coins[v] == 0:
                queue.append(v)
        g[u].clear()
        degree[u] = 0
    # Remove 2 layers of leaves
    for _ in range(2):
        leaves = [i for i in range(n) if degree[i] == 1]
        for u in leaves:
            for v in g[u]:
                g[v].discard(u)
                degree[v] -= 1
            g[u].clear()
            degree[u] = 0
    return sum(len(g[i]) for i in range(n))

