def findShortestCycle(self, n, edges):
    from collections import defaultdict, deque
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    ans = float('inf')
    for src in range(n):
        dist = [-1] * n
        dist[src] = 0
        q = deque([src])
        while q:
            u = q.popleft()
            for v in g[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
                elif dist[v] >= dist[u]:
                    ans = min(ans, dist[u] + dist[v] + 1)
    return ans if ans != float('inf') else -1

