def findMatrix(self, nums):
    from collections import Counter
    cnt = Counter(nums)
    res = []
    while cnt:
        row = list(cnt.keys())
        res.append(row)
        for x in row:
            cnt[x] -= 1
            if cnt[x] == 0:
                del cnt[x]
    return res

def diagonalPrime(self, nums):
    def is_prime(n):
        if n < 2:
            return False
        if n < 4:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True
    n = len(nums)
    res = 0
    for i in range(n):
        if is_prime(nums[i][i]):
