def snail(nums, m, n):
    if m * n != len(nums):
        return []
    matrix = [[0]*n for _ in range(m)]
    idx = 0
    for col in range(n):
        if col % 2 == 0:
            for row in range(m):
                matrix[row][col] = nums[idx]
                idx += 1
        else:
            for row in range(m-1, -1, -1):
                matrix[row][col] = nums[idx]
                idx += 1
    return matrix

