def areDeeplyEqual(o1, o2):
    if type(o1) != type(o2):
        return False
    if isinstance(o1, dict):
        if o1.keys() != o2.keys():
            return False
        return all(areDeeplyEqual(o1[k], o2[k]) for k in o1)
    if isinstance(o1, list):
        if len(o1) != len(o2):
            return False
        return all(areDeeplyEqual(a, b) for a, b in zip(o1, o2))
    return o1 == o2

def compose(functions):
